import{_ as a,o as n,c as e,ai as l}from"./chunks/framework.Ba-VnP44.js";const o=JSON.parse('{"title":"05 功能审查与完善","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/02-lifecycle/review.md","filePath":"ai/productivity/dev-spec/02-lifecycle/review.md"}'),i={name:"ai/productivity/dev-spec/02-lifecycle/review.md"};function p(r,s,t,c,d,b){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="_05-功能审查与完善" tabindex="-1">05 功能审查与完善 <a class="header-anchor" href="#_05-功能审查与完善" aria-label="Permalink to “05 功能审查与完善”">​</a></h1><blockquote><p>第二层 · 开发生命周期。解决「功能写完了但边界、异常、权限没考虑全」——把审查与完善放在一起，按清单逐项核对并补齐，而不是只看功能能不能跑通。</p></blockquote><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用”">​</a></h2><ul><li>一个子任务或功能开发完成，进入自检。</li><li>AI 报告「已完成」，需要判断是不是真的完成。</li><li>交付之前的常规审查。</li></ul><p><strong>不要等到全部写完才第一次审查。</strong> 每个检查点都做局部审查，越晚发现问题，回滚成本越高。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><h3 id="审查清单" tabindex="-1">审查清单 <a class="header-anchor" href="#审查清单" aria-label="Permalink to “审查清单”">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>看什么</th></tr></thead><tbody><tr><td>逻辑与规则</td><td>业务规则有没有实现全，边界条件（空值、零值、重复、越权）有没有处理</td></tr><tr><td>异常与事务</td><td>异常有没有被吞掉，事务边界是否合理，失败时数据会不会处于半状态</td></tr><tr><td>兼容</td><td>接口签名、字段含义、返回结构有没有变，调用方是否受影响</td></tr><tr><td>权限与数据范围</td><td>越权访问有没有拦住，数据隔离条件有没有漏</td></tr><tr><td>测试</td><td>有没有覆盖关键路径和失败路径，断言是不是被放宽或删掉</td></tr><tr><td>改动范围</td><td>有没有混进无关格式化、未使用的 import、调试打印、注释掉的分支、遗留 TODO</td></tr></tbody></table><p>审查时让 AI <strong>只输出问题清单和依据，不修改文件、不宣布通过</strong>。完成判定由人做。</p><h3 id="功能完善" tabindex="-1">功能完善 <a class="header-anchor" href="#功能完善" aria-label="Permalink to “功能完善”">​</a></h3><p>审查发现的问题分两类处理：</p><ul><li><strong>影响正确性</strong>：回到 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/bugfix.html">06 逻辑与 BUG 修复</a> 走修复闭环。</li><li><strong>属于改进优化</strong>：放到 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/refactor.html">07 代码优化与重构</a>，不在这轮顺手做大改。</li></ul><p>完善时保持边界：不改变接口契约，不顺手重构无关代码，补了行为测试再改实现。</p><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>审自己的改动（没有同事时最有用）</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请对本次改动做审查自查，不要修改任何文件，也不要宣布通过。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入：任务验收标准、修改范围与不做项、本轮 git diff。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按清单输出问题（每条给文件:行号和依据）：</span></span>
<span class="line"><span>1. 业务逻辑与边界条件（空值、零值、重复、并发、越权）。</span></span>
<span class="line"><span>2. 异常处理与事务边界。</span></span>
<span class="line"><span>3. 接口、字段、数据兼容性。</span></span>
<span class="line"><span>4. 权限与数据范围。</span></span>
<span class="line"><span>5. 测试是否覆盖关键路径和失败路径，断言是否被放宽或删除。</span></span>
<span class="line"><span>6. 改动范围：无关格式化、未用 import、调试打印、注释掉的分支、遗留 TODO。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最后输出「问题清单」和「需人确认的疑点」两部分。</span></span>
<span class="line"><span>不要写「整体没问题，可以合并」这类判定结论。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div></details><details><summary><strong>边界与异常补齐</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请针对下面这段实现，补齐边界与异常处理。本轮只分析并给出要补的清单，不直接改代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实现：&lt;粘贴代码或描述&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请列出：</span></span>
<span class="line"><span>1. 输入边界：空值、超长、非法格式、重复提交、并发。</span></span>
<span class="line"><span>2. 业务边界：状态不允许、权限不足、数据不存在、依赖不可用。</span></span>
<span class="line"><span>3. 异常路径：每类异常应该怎么处理，是否会被误吞。</span></span>
<span class="line"><span>4. 每条给出「建议处理方式」和「对应的测试用例」。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要为不会发生的场景过度防御，只列真正影响正确性的。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 审查清单逐项过完，问题都列成了清单并带依据。</li><li>[ ] 边界、异常、权限、数据范围都有结论。</li><li>[ ] 没有把调试代码、无关格式化、遗留 TODO 带进来。</li><li>[ ] 断言没被放宽，测试没被删。</li><li>[ ] 审查者没有自行宣布通过，最终判定由人做。</li></ul><p>审查发现问题进入 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/bugfix.html">06 逻辑与 BUG 修复</a>。质量红线见第三层 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/code-quality.html">代码质量规范</a>。</p>`,19)])])}const u=a(i,[["render",p]]);export{o as __pageData,u as default};
